s=session();d=s.resource('dynamodb');t=d.Table('staging-PlatformStaff');eid='f40834f8-4091-7054-0e20-dba35a2793ce';key={'pk':'EMPLOYEE#'+eid,'sk':'PROFILE'};p=t.get_item(Key=key,ConsistentRead=True)['Item'];assert p['employeeId']==eid and p['status']=='ACTIVE' and p['roles']==['bootstrap_admin'];at=datetime.datetime.now(datetime.timezone.utc).isoformat();op='USER_APPROVED_LIMIT_242_'+str(uuid.uuid4());ser=TypeSerializer();av=lambda x:{k:ser.serialize(v)for k,v in x.items()}
